"""
    Computes zscore with precomputed denominator.
    :param observed:
    :param expected:
    :param N:
    :param denom:
    :return:
    """
def zscore_den(observed: Any, expected: Any, N: Any, denom: Any) -> object {
    x = float((observed - expected)) / float(N);
    return (x / denom);
}

"""return a list consisting of multiple lists"""
def get_table_tree(form: Any) -> object {
    table = [];
    if len(form) {
        while form[0] {
            table.append(get_table_tree(form[1:]));
            form[0] -= 1;
        }
        return table;
    } else {
        return [];
    }
}

